Definition LIVKe (A : AS) (d : Z) (m m' : word -> option byte) : Prop :=
  forall q k i, live A q = Some k -> q <> Z_to_bv 64 d -> (0 <= i < k)%Z -> m' (at_ q i) = m (at_ q i).
