Lemma LIVKe_win_d : forall C A m md m' (d kd lo hi : Z), Cok C -> W C A m md -> live A (Z_to_bv 64 d) = Some kd -> (0 <= d < 2 ^ 64)%Z -> (0 <= kd)%Z ->
  (forall a : word, ~ (lo <= u a < hi)%Z -> ~ (d <= u a < d + kd)%Z -> m' a = m a) -> (c_top C - LSTK <= lo)%Z -> (hi <= c_top C)%Z ->
