Lemma rb_words_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (i j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTb m ->
  (0 <= i < hd)%Z -> (0 <= j)%Z -> (Z.of_nat n = wplsi - 1 - j)%Z ->
  regs_agree (fun x => In x [7; 28; 29; 30; 31]%list) r0 r ->
  getr r 7 = Z_to_bv 64 (datas + 8 * wpls * i + 4 * j) -> getr r 28 = Z_to_bv 64 (datas + 8 * wpls * i + 4 * wpls + 4 * j) ->
  getr r 29 = Z_to_bv 64 (datad + 4 * wpld * i + 2 * j) -> getr r 6 = Z_to_bv 64 (datad + 2 * wplsi + 4 * wpld * i) ->
  getr r 11 = Z_to_bv 64 tab ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTb m' -> regs_agree (fun x => In x [7; 28; 29; 30; 31]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x9434c : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x94378 : word) m al_rom) md) S.
