(* [comment removed for export] *)
Lemma rb_rows_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (i : Z),
  W C A m md -> POSTM C Ar s mB m -> FTb m ->
  (0 <= i)%Z -> (Z.of_nat n = hd - 1 - i)%Z ->
  regs_agree (fun x => In x [6; 7; 8; 9; 14; 16; 28; 29; 30; 31]%list) r0 r ->
  getr r 14 = Z_to_bv 64 i -> getr r 8 = Z_to_bv 64 (datas + 8 * wpls * i) -> getr r 16 = Z_to_bv 64 (datas + 8 * wpls * i + 4 * wpls) ->
  getr r 9 = Z_to_bv 64 (datad + 4 * wpld * i) ->
  getr r 13 = Z_to_bv 64 wplsi -> getr r 20 = Z_to_bv 64 (4 * wpld) -> getr r 18 = Z_to_bv 64 (8 * wpls) ->
  getr r 5 = Z_to_bv 64 (datad + 2 * wplsi) -> getr r 17 = Z_to_bv 64 hd -> getr r 11 = Z_to_bv 64 tab ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTb m' -> regs_agree (fun x => In x [6; 7; 8; 9; 14; 16; 28; 29; 30; 31]%list) r0 r' ->
     getr r' 14 = Z_to_bv 64 (hd - 1) ->
     realizes SEGS (mkCfg (mkst r' (0x9434c : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x94360 : word) m al_rom) md) S.
Proof using Hwi3 Hwi2 Hwi1 Hwpls Hwpld Hhd Htab Hds Hal Hdd Lt Hks Ls Ld0 Ldr Hkd Ld SUB CK ks kd P16 PINS.
